class SafeBox
    private define password as string;

    method constructor(aPassword as string)
        this.password <- aPassword;
    endMethod

    public method Open(attempt as string) as integer
        if attempt = this.password then
            return 1;
        else
            return 0;
        endIf
    endMethod
endClass

algorithm RunSafeBox
    define password as string;
    define attempt as string;
    define box as SafeBox;
    read password;
    read attempt;
    box <- new SafeBox(password);
    write box.Open(attempt);
endAlgorithm
